pub const table_bytes: usize = @sizeOf(@TypeOf(stage1)) + @sizeOf(@TypeOf(stage2)) + @sizeOf(@TypeOf(stage3)) + @sizeOf(@TypeOf(mappings));

fn mapping(cp: u21) Mapping {
    if (cp > 0x10ffff) return .{ .uppercase = 0, .lowercase = 0, .titlecase = 0 };
    const mid = stage1[cp >> s1];
    const leaf = stage2[(@as(usize, mid) << (s1 - s2)) | (cp >> s2 & ((1 << (s1 - s2)) - 1))];
    const id = stage3[(@as(usize, leaf) << s2) | (cp & ((1 << s2) - 1))];
    return mappings[id];
}

fn shifted(cp: u21, delta: i17) u21 {
    return @intCast(@as(i32, cp) + @as(i32, delta));
}

pub fn simpleUppercase(cp: u21) u21 {
    if (cp >= 'a' and cp <= 'z') return cp - 0x20;
    return shifted(cp, mapping(cp).uppercase);
}

pub fn simpleLowercase(cp: u21) u21 {
    if (cp >= 'A' and cp <= 'Z') return cp + 0x20;
    return shifted(cp, mapping(cp).lowercase);
}

pub fn simpleTitlecase(cp: u21) u21 {
    if (cp >= 'a' and cp <= 'z') return cp - 0x20;
    return shifted(cp, mapping(cp).titlecase);
}
